20	// explainRepoRef is a parsed `explain --repo` value: either an owner/name slug
21	// (possibly given with a gh/ prefix) or a raw repo ULID that still needs a
22	// control-plane lookup to become owner/name.
23	type explainRepoRef struct {
24		owner, repo string // owner/name form (lowercased)
25		repoID      string // bare-ULID form
26	}
27	
28	// parseExplainRepoFlag parses the --repo flag value. Accepted shapes:
29	// `owner/name`, `gh/owner/name` (leading slash optional), or a bare repo ULID.
30	// owner/name reuse the GitHub charset validation of the mirror clone-ref
31	// parser and come back lowercased, matching what the control plane persists.
32	func parseExplainRepoFlag(value string) (explainRepoRef, error) {
33		v := strings.TrimSpace(value)
34		if v == "" {
35			return explainRepoRef{}, errors.New("--repo requires a value: owner/name, gh/owner/name, or a repo ID")
36		}
37		if strings.Contains(v, "/") {
38			// Normalize owner/name to the gh/owner/name clone-ref shape so
39			// parseMirrorCloneRef's charset validation applies to both forms.
40			ref := strings.TrimPrefix(v, "/")
41			if !strings.HasPrefix(ref, "gh/") {
42				ref = "gh/" + ref
43			}
44			_, owner, repo, err := parseMirrorCloneRef(ref)
45			if err != nil {
46				return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID: %w", value, err)
47			}
48			return explainRepoRef{owner: owner, repo: repo}, nil
49		}
50		if !looksLikeULID(v) {
51			return explainRepoRef{}, fmt.Errorf("invalid --repo %q: expected owner/name, gh/owner/name, or a repo ID (ULID)", value)
52		}
53		return explainRepoRef{repoID: v}, nil
54	}
