56	// resolveExplainRepoID resolves a raw repo ULID to its owner/name via the
57	// control plane's by-id lookup (the same call `entire repo get <ulid>` uses).
58	// A clusterFlag naming a cluster in a different federation dials that
59	// cluster's core instead of the active context's, matching how the placement
60	// lookup routes (see listPullablePlacements).
61	func resolveExplainRepoID(cmd *cobra.Command, repoID, clusterFlag string) (owner, repo string, err error) {
62		runWithCore, err := coreRunnerForCluster(clusterFlag)
63		if err != nil {
64			return "", "", err
65		}
66		var fullName string
67		err = runWithCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
68			r, err := c.GetRepo(ctx, coreapi.GetRepoParams{RepoId: repoID})
69			if err != nil {
70				if isCoreNotFound(err) {
71					return fmt.Errorf("no repository with ID %q visible from your login", repoID)
72				}
73				return fmt.Errorf("look up repository %q: %w", repoID, err)
74			}
75			fullName = r.FullName.Or("")
76			return nil
77		})
78		if err != nil {
79			return "", "", err
80		}
81		owner, repo, ok := strings.Cut(strings.ToLower(fullName), "/")
82		if !ok || owner == "" || repo == "" {
83			return "", "", fmt.Errorf("repository %q has an unexpected full name %q (want owner/name)", repoID, fullName)
84		}
85		return owner, repo, nil
86	}
