88	// explainRepoIsCurrent reports whether owner/repo names the same repository as
89	// the cwd worktree's origin remote (handles ssh, https, and entire:// mirror
90	// URL forms). --repo is GitHub-scoped (gh/owner/name), so a non-GitHub origin
91	// with a coincidentally matching owner/name must not count as the current
92	// repo. Best-effort: any lookup or parse failure returns false, so explain
93	// proceeds with the cross-repo fetch path.
94	func explainRepoIsCurrent(ctx context.Context, owner, repo string) bool {
95		curForge, curOwner, curRepo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
96		if err != nil || curForge != "gh" {
97			return false
98		}
99		return strings.EqualFold(curOwner, owner) && strings.EqualFold(curRepo, repo)
100	}
