102	// resolveExplainRepoFetchURL resolves the entire:// mirror URL to fetch a
103	// foreign repo's checkpoint ref from: pullable placements via the core API
104	// (the same authority `repo clone` uses), then the shared placement picker
105	// with explain-specific wording and the --cluster escape hatch.
106	func resolveExplainRepoFetchURL(cmd *cobra.Command, owner, repo, clusterFlag string) (string, error) {
107		placements, err := listPullablePlacements(cmd, owner, repo, clusterFlag)
108		if err != nil {
109			return "", err
110		}
111		if len(placements) == 0 {
112			return "", fmt.Errorf("no mirror found for /gh/%s/%s; cross-repo explain fetches checkpoints from the repo's Entire mirror", owner, repo)
113		}
114		chosen, err := selectPlacement(cmd, placements, clusterFlag, placementPicker{
115			selector: "--cluster",
116			title:    "This repo is mirrored on more than one cluster — pick one to fetch the checkpoint from",
117			action:   "Explain",
118		})
119		if err != nil {
120			return "", err
121		}
122		// chosen.ClusterHost is server-provided but interpolated into the entire://
123		// URL like a user-supplied --cluster, so apply the same anti-token-leak
124		// guard before building it (see repo clone).
125		if err := validateClusterHost(chosen.ClusterHost); err != nil {
126			return "", fmt.Errorf("mirror has an invalid cluster host %q: %w", chosen.ClusterHost, err)
127		}
128		return mirrorCloneURL(chosen.ClusterHost, owner, repo), nil
129	}
