131	// prepareCrossRepoExplain resolves --repo/--cluster and, when the target repo
132	// differs from the cwd repo, fetches the checkpoint's per-checkpoint ref from
133	// that repo's Entire mirror into the cwd repo's object store. After a nil
134	// return, the normal explain flow resolves the checkpoint as if it were local.
135	// When --repo names the cwd repo it is a no-op (behavior identical to no flag).
136	func prepareCrossRepoExplain(cmd *cobra.Command, repoFlag, clusterFlag, target string) error {
137		ref, err := parseExplainRepoFlag(repoFlag)
138		if err != nil {
139			return err
140		}
141		// Everything past flag parsing is a runtime failure (network, git), not a
142		// usage mistake — don't dump usage text on it.
143		cmd.SilenceUsage = true
144		owner, repoName := ref.owner, ref.repo
145		if ref.repoID != "" {
146			owner, repoName, err = resolveExplainRepoID(cmd, ref.repoID, clusterFlag)
147			if err != nil {
148				return err
149			}
150		}
151		if explainRepoIsCurrent(cmd.Context(), owner, repoName) {
152			return nil
153		}
154		// A prefix cannot name a per-checkpoint ref, so cross-repo needs the full ID.
155		cid, err := id.NewCheckpointID(target)
156		if err != nil {
157			return fmt.Errorf("--repo requires a full checkpoint ID (12-char hex or 26-char ULID); a prefix cannot be resolved cross-repo: %w", err)
158		}
159		url, err := resolveExplainRepoFetchURL(cmd, owner, repoName, clusterFlag)
160		if err != nil {
161			return err
162		}
163		return fetchCrossRepoCheckpoint(cmd.Context(), cmd.ErrOrStderr(), url, owner+"/"+repoName, cid)
164	}
