166	// fetchCrossRepoCheckpoint fetches cid's per-checkpoint ref
167	// (refs/entire/checkpoints/<shard>/<id>) from url into the cwd repo's object
168	// store. Separated from URL resolution so tests can exercise the fetch +
169	// explain flow against a file:// remote without the core API or
170	// git-remote-entire.
171	func fetchCrossRepoCheckpoint(ctx context.Context, errW io.Writer, url, ownerRepo string, cid id.CheckpointID) error {
172		refName, err := checkpoint.RefName(cid)
173		if err != nil {
174			// Defensive only: cid is already validated by the caller.
175			return err //nolint:wrapcheck // RefName's error is self-describing
176		}
177		stop := startSpinner(errW, "Fetching checkpoint from "+ownerRepo)
178		fetchErr := remote.FetchCheckpointRefFrom(ctx, url, refName)
179		stop(fetchErr == nil)
180		if fetchErr == nil {
181			return nil
182		}
183		if errors.Is(fetchErr, plumbing.ErrReferenceNotFound) {
184			return fmt.Errorf("checkpoint %s not found in the mirror for %s; repos using the legacy branch-based checkpoint store (or an external checkpoint_remote) are not supported cross-repo yet", cid, ownerRepo)
185		}
186		return fmt.Errorf("fetch checkpoint %s from %s: %w", cid, ownerRepo, fetchErr)
187	}
188

240		return false
241	}
