243	// matchCheckpointPrefixWithRemoteFallback returns all committed checkpoints
244	// whose ID starts with prefix. On a local miss, fetches metadata from the
245	// remote (treeless origin → full origin chain) and retries once with a fresh
246	// lookup. The returned lookup may differ from the input on retry.
247	func matchCheckpointPrefixWithRemoteFallback(ctx context.Context, errW io.Writer, lookup *explainCheckpointLookup, prefix string) ([]id.CheckpointID, *explainCheckpointLookup) {
248		matches := matchCheckpointPrefix(lookup, prefix)
249		if len(matches) > 0 {
250			return matches, lookup
251		}
252	
253		// git-refs primary: there is no single metadata branch to fetch — each
254		// checkpoint is its own ref. When the prefix is a full checkpoint ID (the
255		// Entire-Checkpoint commit trailer always is), fetch that one ref directly,
256		// then re-list. A shorter prefix cannot be fetched per-ref, and under a
257		// refs primary there is no v1 metadata branch to fetch either, so a
258		// short-prefix miss stays local-only.
259		if cpCfg, _ := settings.LoadCheckpointsConfig(ctx); checkpoint.PrimaryIsRefs(cpCfg) { //nolint:errcheck // fail-soft: bad config surfaces via Open elsewhere
260			if cid, err := id.NewCheckpointID(prefix); err != nil {
261				logging.Debug(ctx, "explain: prefix is not a full checkpoint ID; refs-primary store cannot fetch by prefix, treating as no match",
262					slog.String("prefix", prefix))
263			} else {
264				// cid is already validated by NewCheckpointID above, so RefName can't
265				// error here; the guard is defensive — treat it as a local-only miss
266				// rather than fetch a malformed ref.
267				refName, refErr := checkpoint.RefName(cid)
268				if refErr != nil {
269					return nil, lookup
270				}
271				stop := startSpinner(errW, "Fetching checkpoint from remote")
272				fetchErr := FetchCheckpointRef(ctx, refName)
273				stop(false)
274				if fetchErr == nil {
275					fresh, freshErr := newExplainCheckpointLookup(ctx)
276					if freshErr == nil {
277						if m := matchCheckpointPrefix(fresh, prefix); len(m) > 0 {
278							return m, fresh
279						}
280						_ = fresh.Close()
281					} else {
282						// The collapse to "no match" below reads to the user as
283						// "doesn't exist"; record what actually failed (issue #1815).
284						logging.Debug(ctx, "explain: lookup rebuild after checkpoint ref fetch failed; treating as no match",
285							slog.String("prefix", prefix),
286							slog.String("error", freshErr.Error()))
287					}
288				} else {
289					logging.Debug(ctx, "explain: on-demand checkpoint ref fetch failed; treating as no match",
290						slog.String("ref", refName.String()),
291						slog.String("error", fetchErr.Error()))
292				}
293			}
294			return nil, lookup
295		}
296	
297		stop := startSpinner(errW, "Fetching checkpoint metadata from remote")
298		_, v1Repo, v1Err := getMetadataTree(ctx)
299		if v1Repo != nil {
300			_ = v1Repo.Close()
301		}
302		stop(false)
303		if v1Err != nil {
304			logging.Debug(ctx, "explain: metadata branch fetch failed; treating as no match",
305				slog.String("prefix", prefix),
306				slog.String("error", v1Err.Error()))
307			return nil, lookup
308		}
309		fresh, freshErr := newExplainCheckpointLookup(ctx)
310		if freshErr != nil {
311			logging.Debug(ctx, "explain: lookup rebuild after metadata fetch failed; treating as no match",
312				slog.String("prefix", prefix),
313				slog.String("error", freshErr.Error()))
314			return nil, lookup
315		}
316		return matchCheckpointPrefix(fresh, prefix), fresh
317	}
318	
319	func matchCheckpointPrefix(lookup *explainCheckpointLookup, prefix string) []id.CheckpointID {
320		var matches []id.CheckpointID
321		for _, info := range lookup.committed {
322			if strings.HasPrefix(info.CheckpointID.String(), prefix) {
323				matches = append(matches, info.CheckpointID)
324			}
325		}
326		return matches
327	}
