329	// errCheckpointHasNoSessions distinguishes "this checkpoint has zero sessions"
330	// from checkpoint.ErrCheckpointNotFound — callers using errors.Is on the
331	// not-found sentinel were getting wrong-fault UX (e.g. "did you mistype the
332	// ID?") for a legitimate empty-checkpoint edge case.
333	var errCheckpointHasNoSessions = errors.New("checkpoint has no sessions")
334	
335	// resolveSessionIndex maps the user's --session-index value (or the implicit
336	// default) onto a valid 0-based offset within summary.Sessions.
337	func resolveSessionIndex(summary *checkpoint.CheckpointSummary, requested int) (int, error) {
338		if summary == nil {
339			return 0, checkpoint.ErrCheckpointNotFound
340		}
341		if len(summary.Sessions) == 0 {
342			return 0, errCheckpointHasNoSessions
343		}
344		if requested < 0 {
345			return len(summary.Sessions) - 1, nil
346		}
347		if requested >= len(summary.Sessions) {
348			return 0, fmt.Errorf("session index %d out of range (checkpoint has %d sessions)", requested, len(summary.Sessions))
349		}

496	func runExplain(ctx context.Context, w, errW io.Writer, sessionID, commitRef, checkpointID, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
497		// Count mutually exclusive flags (--commit and --checkpoint are mutually exclusive)
498		// --session is now a filter for the list view, not a separate mode
499		flagCount := 0
500		if commitRef != "" {
501			flagCount++
502		}
503		if checkpointID != "" {
504			flagCount++
505		}
506		// If --session is combined with --commit or --checkpoint, that's still an error
507		if sessionID != "" && flagCount > 0 {
508			return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
509		}
510		if flagCount > 1 {
511			return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
512		}
513	
514		// Route to appropriate handler
515		if target != "" {
516			return runExplainAuto(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
517		}
518		if commitRef != "" {
519			return runExplainCommit(ctx, w, errW, commitRef, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
520		}
521		if checkpointID != "" {
522			return runExplainCheckpoint(ctx, w, errW, checkpointID, noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds)
523		}
524	
525		// Default or with session filter: show list view (optionally filtered by session)
526		return runExplainBranchWithFilter(ctx, w, errW, noPager, sessionID)
527	}
