529	// explainTargetNotFoundError reports that the requested checkpoint target
530	// matched no committed or temporary checkpoint. It unwraps to
531	// checkpoint.ErrCheckpointNotFound so callers' errors.Is contracts keep
532	// working, while runExplainAuto can distinguish this resolution miss from a
533	// failure AFTER a successful match that happens to wrap the same sentinel
534	// (e.g. "failed to save summary: checkpoint not found" from a backfill
535	// against a backend missing the checkpoint) — those must surface verbatim,
536	// not be masked by the commit fallback's "no checkpoint or commit found".
537	type explainTargetNotFoundError struct{ target string }
538	
539	func (e *explainTargetNotFoundError) Error() string {
540		return fmt.Sprintf("%s: %s", checkpoint.ErrCheckpointNotFound, e.target)
541	}
542	
543	func (e *explainTargetNotFoundError) Unwrap() error { return checkpoint.ErrCheckpointNotFound }
544	
545	// shouldFallBackToCommitResolution reports whether the checkpoint path's error
546	// means "the target matched nothing", the only outcome that may fall through
547	// to git commit resolution.
548	func shouldFallBackToCommitResolution(err error) bool {
549		var targetMiss *explainTargetNotFoundError
550		return errors.As(err, &targetMiss)
551	}
552	
553	// runExplainAuto resolves a positional target as either a checkpoint ID
554	// (or prefix) or a git commit ref. Ordering: checkpoint path first (which
555	// also handles shadow-branch temp checkpoints), falling back to commit
556	// resolution only on the target-miss error (explainTargetNotFoundError).
557	// --generate runs an ambiguity pre-check to avoid writing a summary to the
558	// wrong checkpoint on short-prefix collisions.
559	func runExplainAuto(ctx context.Context, w, errW io.Writer, target string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
560		stop := startSpinner(errW, "Loading checkpoints")
561		lookup, lookupErr := newExplainCheckpointLookup(ctx)
562		stop(false)
563		if lookup != nil {
564			defer lookup.Close()
565		}
566		if generate {
567			if err := runExplainAutoAmbiguityGuard(ctx, target, lookup, lookupErr); err != nil {
568				return err
569			}
570		}
571		checkpointErr := runExplainCheckpointWithLookup(ctx, w, errW, target, noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, lookupErr, summaryTimeoutSeconds)
572		if checkpointErr == nil {
573			return nil
574		}
575		// Fall back to commit resolution ONLY when nothing (committed or temp)
576		// matched the target. Errors from steps AFTER a successful match — even
577		// ones wrapping checkpoint.ErrCheckpointNotFound, like a summary backfill
578		// failing against a backend missing the checkpoint — surface verbatim;
579		// falling back would misreport them as "no checkpoint or commit found"
580		// for a target that DID resolve. errCannotGenerateTemporaryCheckpoint
581		// likewise signals we matched a temp checkpoint but --generate is
582		// unsupported for it; a commit fallback there would produce a misleading
583		// "no trailer" error for the shadow-branch commit.
584		if !shouldFallBackToCommitResolution(checkpointErr) {
585			return checkpointErr
586		}
587		logging.Debug(ctx, "explain auto: checkpoint lookup failed, trying commit fallback",
588			slog.String("target", target),
589			slog.String("checkpoint_error", checkpointErr.Error()))
590	
591		if lookupErr != nil {
592			// Composed message beats errors.Join here — the latter renders
593			// two lines (one per error) and users act on the first/stale one.
594			return fmt.Errorf("no checkpoint matched %q, and commit fallback failed: %w", target, lookupErr)
595		}
596		hash, ambiguousMatches, resolveErr := resolveCommitUnambiguous(lookup.repo, target)
597		if resolveErr != nil {
598			if errors.Is(resolveErr, errAmbiguousCommitPrefix) {
599				renderAmbiguousPrefixFailure(errW, target, "commits", buildAmbiguousCommitMatches(lookup.repo, ambiguousMatches))
600				return NewSilentError(resolveErr)
601			}
602			logging.Debug(ctx, "explain auto: git ref resolution failed",
603				slog.String("target", target),
604				slog.String("error", resolveErr.Error()))
605			return fmt.Errorf("no checkpoint or commit found matching %q", target)
606		}
607		commit, commitErr := lookup.repo.CommitObject(hash)
608		if commitErr != nil {
609			return fmt.Errorf("failed to get commit %s: %w", abbreviateCommitHash(lookup.repo, hash), commitErr)
610		}
611		cpID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
612		if !hasCheckpoint {
613			// Side-effect modes must error — silently succeeding would leave
614			// scripts unable to distinguish "done" from "didn't happen".
615			if generate || rawTranscript {
616				return fmt.Errorf("cannot %s: commit %s has no Entire-Checkpoint trailer", generateOrRawLabel(generate), abbreviateCommitHash(lookup.repo, hash))
617			}
618			printNoTrailerMessage(w, lookup.repo, hash)
619			return nil
620		}
621		logging.Debug(ctx, "explain auto: resolved commit to checkpoint via trailer",
622			slog.String("target", target),
623			slog.String("commit", abbreviateCommitHash(lookup.repo, hash)),
624			slog.String("checkpoint_id", cpID.String()))
625		if err := runExplainCheckpointWithLookup(ctx, w, errW, cpID.String(), noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, nil, summaryTimeoutSeconds); err != nil {
626			// The user typed a commit, not this checkpoint ID — without the
627			// trailer linkage the error reads as if they asked for an unknown ID.
628			return fmt.Errorf("commit %s references checkpoint %s via its Entire-Checkpoint trailer: %w", abbreviateCommitHash(lookup.repo, hash), cpID, err)
629		}
630		return nil
631	}
