633	// runExplainAutoAmbiguityGuard refuses --generate when the positional
634	// target resolves as both a git revision and a committed-checkpoint prefix.
635	// Writing a summary to the wrong checkpoint is destructive; read-only flows
636	// tolerate the same ambiguity by preferring the checkpoint path.
637	//
638	// Best-effort: on repo/list failures we return nil so the main flow
639	// surfaces the real error instead of double-reporting.
640	func runExplainAutoAmbiguityGuard(ctx context.Context, target string, lookup *explainCheckpointLookup, lookupErr error) error {
641		// Targets longer than the longest possible checkpoint ID (a 26-char ULID)
642		// can't be a prefix of one, so they can't be an ambiguous checkpoint target.
643		if len(target) > id.MaxIDLength {
644			return nil
645		}
646		if lookupErr != nil {
647			logging.Warn(ctx, "explain ambiguity guard degraded: failed to prepare checkpoint lookup",
648				"target", target,
649				"error", lookupErr)
650			return nil
651		}
652		hash, err := lookup.repo.ResolveRevision(plumbing.Revision(target))
653		if err != nil {
654			return nil //nolint:nilerr // target isn't a git ref
655		}
656		if lookup == nil {
657			logging.Warn(ctx, "explain ambiguity guard degraded: checkpoint lookup unavailable",
658				"target", target)
659			return nil
660		}
661		if lookup.committed == nil {
662			logging.Warn(ctx, "explain ambiguity guard degraded: committed checkpoint list unavailable",
663				"target", target)
664			return nil
665		}
666		for _, info := range lookup.committed {
667			if strings.HasPrefix(info.CheckpointID.String(), target) {
668				return fmt.Errorf("ambiguous target %q with --generate: matches both git revision %s and checkpoint prefix (e.g. %s)\nUse --commit <ref> or --checkpoint <id> to disambiguate", target, abbreviateCommitHash(lookup.repo, *hash), info.CheckpointID)
669			}
670		}
671		return nil
672	}
