674	// runExplainCheckpoint explains a specific checkpoint.
675	// Supports both committed checkpoints (by checkpoint ID) and temporary checkpoints (by git SHA).
676	// First tries to match committed checkpoints, then falls back to temporary checkpoints.
677	// When generate is true, generates an AI summary for the checkpoint.
678	// When force is true, regenerates even if a summary already exists.
679	// When rawTranscript is true, outputs only the raw transcript file (JSONL format).
680	// When searchAll is true, searches all commits without branch/depth limits (used for finding associated commits).
681	//
682	
683	func runExplainCheckpoint(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, summaryTimeoutSeconds int) error {
684		return runExplainCheckpointWithLookup(ctx, w, errW, checkpointIDPrefix, noPager, verbose, full, rawTranscript, generate, force, searchAll, nil, nil, summaryTimeoutSeconds)
685	}
