687	func runExplainCheckpointWithLookup(ctx context.Context, w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool, lookup *explainCheckpointLookup, lookupErr error, summaryTimeoutSeconds int) error {
688		ownLookup := false
689		if lookup == nil {
690			var err error
691			lookup, err = newExplainCheckpointLookup(ctx)
692			if err != nil {
693				return err
694			}
695			ownLookup = true

695			ownLookup = true
696		} else if lookupErr != nil {
697			return lookupErr
698		}
699		initialLookup := lookup
700		defer func() {
