57	// runExplainExport handles --json, --transcript, and --raw-transcript with an
58	// explicit --session-index. JSON is metadata-only (no transcript bytes
59	// embedded); transcript bytes always stream to stdout from a flag, never from
60	// the JSON envelope.
61	func runExplainExport(ctx context.Context, w, errW io.Writer, opts explainExportOptions) error {
62		hasTarget := opts.target != "" || opts.commitRef != "" || opts.checkpointFlag != ""
63	
64		switch {
65		case opts.transcript || opts.rawTranscript:
66			if !hasTarget {
67				flagName := "--transcript"
68				if opts.rawTranscript {
69					flagName = "--raw-transcript"
70				}
71				return fmt.Errorf("%s requires a checkpoint ID or commit SHA (positional), --checkpoint/-c, or --commit flag", flagName)
72			}
73			return runExplainStreamTranscript(ctx, w, errW, opts)
74		case opts.json:
75			if !hasTarget {
76				return runExplainListJSON(ctx, w, errW, opts.sessionFilter, opts.listLimit)
77			}
78			return runExplainCheckpointJSON(ctx, w, errW, opts)
79		default:
80			// The cobra layer guarantees at least one mode flag is set before
81			// dispatching here; this branch is a defensive guard against a
82			// future caller invoking runExplainExport directly with no mode.
83			return errors.New("internal: runExplainExport called without an output mode (json, transcript, or raw-transcript)")
84		}
85	}
