102		prefix := opts.checkpointFlag
103		if prefix == "" {
104			prefix = opts.target
105		}
106		if prefix == "" {
107			return id.CheckpointID(""), nil, errors.New("missing checkpoint target")
108		}
109	
110		lookup, lookupErr := newExplainCheckpointLookup(ctx)
111		if lookupErr != nil {
112			return id.CheckpointID(""), nil, lookupErr
113		}
114	
115		matches, resolvedLookup := matchCheckpointPrefixWithRemoteFallback(ctx, errW, lookup, prefix)
116		if resolvedLookup != lookup {
117			_ = lookup.Close()
118			lookup = resolvedLookup
119		}
120		switch len(matches) {
121		case 1:
