250		}
251		stop := startSpinner(errW, "Fetching checkpoint from "+ownerRepo)
252		fetchErr := remote.FetchCheckpointRefInto(ctx, tmpDir, url, refName)
253		stop(fetchErr == nil)
254		if fetchErr != nil {
255			if errors.Is(fetchErr, plumbing.ErrReferenceNotFound) {
256				return nil, fmt.Errorf("checkpoint %s not found in the mirror for %s; repos using the legacy branch-based checkpoint store (or an external checkpoint_remote) are not supported cross-repo yet", cid, ownerRepo)
257			}
258			return nil, fmt.Errorf("fetch checkpoint %s from %s: %w", cid, ownerRepo, fetchErr)
259		}
260		repo, err := gitrepo.OpenPath(tmpDir)
261		if err != nil {
262			return nil, fmt.Errorf("open temp repo for cross-repo checkpoint: %w", err)
263		}
264		// No fetchers: the single fetched ref brought every object with it
265		// (unfiltered fetch), and an on-demand fetch would dial the cwd repo's
266		// checkpoint remote — the wrong repo.
267		store := checkpoint.NewRefsReadStore(repo)
268		committed, err := store.List(ctx)
269		if err != nil {
270			_ = repo.Close()
271			return nil, fmt.Errorf("list fetched cross-repo checkpoint: %w", err)
272		}
273		return &explainCheckpointLookup{repo: repo, store: store, committed: committed, noRemoteFallback: true}, nil
274	}
